{
  "manifest_version": 3,
  "name": "Temu 店铺监测",
  "version": "0.1.0",
  "description": "监测 Temu 后台在售数量下降 / 商品流量异常，异常时发飞书告警。数据仅在本机处理，不上传任何服务器。",
  "permissions": ["storage", "alarms", "tabs", "idle"],
  "host_permissions": [
    "https://agentseller.temu.com/*",
    "https://open.feishu.cn/*",
    "https://open.larksuite.com/*"
  ],
  "background": { "service_worker": "background.js" },
  "action": { "default_popup": "popup.html", "default_title": "Temu 店铺监测" },
  "options_page": "options.html",
  "content_scripts": [
    {
      "matches": ["https://agentseller.temu.com/*"],
      "js": ["content.js"],
      "run_at": "document_start"
    }
  ],
  "web_accessible_resources": [
    { "resources": ["inject.js"], "matches": ["https://agentseller.temu.com/*"] }
  ]
}

{
  "name": "temu-monitor",
  "version": "1.0.0",
  "description": "Temu Seller Central 多店铺在售数量 + 商品流量异常 自动化监测，飞书告警",
  "type": "module",
  "scripts": {
    "login": "node src/cli.js login",
    "calibrate": "node src/cli.js calibrate",
    "probe": "node src/probe.js",
    "once": "node src/cli.js once",
    "start": "node src/cli.js start"
  },
  "dependencies": {
    "playwright": "^1.49.0"
  }
}

content.content:
1	// Service worker：接收接口数据 → 按【店铺名】分别解析/对比/告警。
2	// 多店铺：同一账号下有多个店(HomeCove/Twilight Cove/Agnis)，切到哪个店就记哪个店，各自独立快照与告警。
3	// 数据只存本机 chrome.storage.local，不上传任何服务器。
4	
5	const GOODS_URL = 'https://agentseller.temu.com/goods/list';
6	const DEFAULT_CONFIG = { webhook: '', intervalMinutes: 15, enabled: true, storeName: '' };
7	
8	// ---------------- 解析 ----------------
9	function parseCountStatus(body) {
10	  try {
11	    const j = JSON.parse(body);
12	    const list = j && j.result && j.result.skcTopStatusCountList;
13	    if (!Array.isArray(list)) return null;
14	    const pick = (s) => {
15	      const x = list.find((e) => e && e.skcTopStatus === s);
16	      return x && typeof x.skcTotal === 'number' ? x.skcTotal : null;
17	    };
18	    return { onSale: pick(100), unpublished: pick(0), removed: pick(200), deleted: pick(300) };
19	  } catch (e) { return null; }
20	}
21	function parsePageQuery(body) {
22	  try {
23	    const j = JSON.parse(body);
24	    const r = j && j.result;
25	    if (!r) return null;
26	    return { total: r.total };
27	  } catch (e) { return null; }
28	}
29	
30	// ---------------- 存取 ----------------
31	async function getConfig() {
32	  const { config } = await chrome.storage.local.get('config');
33	  return Object.assign({}, DEFAULT_CONFIG, config || {});
34	}
35	async function getStores() {
36	  const { stores } = await chrome.storage.local.get('stores');
37	  return stores || {};
38	}
39	async function saveStores(stores) {
40	  await chrome.storage.local.set({ stores });
41	}
42	// 更新某店的最新读数
43	async function updateStoreLatest(name, patch) {
44	  const stores = await getStores();
45	  const s = stores[name] || { latest: {}, snapshot: {} };
46	  s.latest = Object.assign({}, s.latest, patch, { ts: Date.now() });
47	  stores[name] = s;
48	  await saveStores(stores);
49	  return s;
50	}
51	
52	// ---------------- 飞书 ----------------
53	async function sendFeishu(webhook, title, lines) {
54	  if (!webhook) return { ok: false, msg: '未配置飞书 webhook' };
55	  const card = {
56	    msg_type: 'interactive',
57	    card: {
58	      header: { title: { tag: 'plain_text', content: title }, template: 'red' },
59	      elements: [{ tag: 'div', text: { tag: 'lark_md', content: lines.join('\n') } }],
60	    },
61	  };
62	  try {
63	    const resp = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
64	    const data = await resp.json().catch(() => ({}));
65	    const ok = resp.ok && (data.code === 0 || data.StatusCode === 0 || data.code === undefined);
66	    return { ok, msg: ok ? '已发送' : ('飞书返回：' + JSON.stringify(data)) };
67	  } catch (e) {
68	    return { ok: false, msg: '发送失败：' + (e && e.message) };
69	  }
70	}
71	
72	// ---------------- 商品明细 → 带链接的告警行 ----------------
73	// 后台商品操作都是弹窗、无深链，唯一稳定可点的是编辑页（实测格式：SPU ID 即 productId）。
74	function editLink(productId) {
75	  return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId;
76	}
77	// items：当前页可见的限流/下降商品（content.js 扫描 DOM 得到）；total：chip 全量计数。
78	function itemLines(items, total) {
79	  const lines = [];
80	  if (Array.isArray(items) && items.length) {
81	    for (const it of items) {
82	      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
83	      lines.push('• [' + nm + '](' + editLink(it.productId) + ')  SKC ' + (it.skc || '-'));
84	    }
85	    if (typeof total === 'number' && total > items.length) {
86	      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
87	    }
88	  } else if (typeof total === 'number' && total > 0) {
89	    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
90	  }
91	  return lines;
92	}
93	
94	// 让 content.js 主动点「商品流量待关注」筛选，捞出这几条被限流的具体商品（productId+name+skc）
95	async function scanWatchViaTab() {
96	  const tab = await getGoodsTab();
97	  if (!tab) return null;
98	  return await sendTabRetry(tab.id, { cmd: 'scanWatchList' }, 3);
99	}
100	
101	// ---------------- 对比 & 告警（按店） ----------------
102	// 按店串行：同一店的多条读数消息（切店时常一秒内来两条）排队逐个处理，
103	// 避免"都读到旧快照各报一次"的竞态导致同一事件重复告警。
104	const alertChains = {};
105	function diffAndAlert(name) {
106	  const prev = alertChains[name] || Promise.resolve();
107	  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
108	  alertChains[name] = next;
109	  return next;
110	}
111	
112	async function _diffAndAlert(name) {
113	  const cfg = await getConfig();
114	  if (!cfg.enabled) return;
115	  const stores = await getStores();
116	  const s = stores[name];
117	  if (!s) return;
118	  const latest = s.latest || {};
119	  const snap = s.snapshot || {};
120	  const events = [];
121	
122	  // 在售数量下降：数字告警（被动监测第一时间发现），diffOnSale 在轮巡时带具体商品名+链接点名。
123	  // v3 曾移除此项（担心与 diffOnSale 重复），但 diffOnSale 只在空闲轮巡触发，移除后用户手动刷新/页面
124	  // 自然浏览时下架完全漏报——现在恢复，与 diffOnSale 互补：此处报数字，轮巡补点名。
125	  if (typeof latest.onSale === 'number' && typeof snap.onSale === 'number' && latest.onSale < snap.onSale) {
126	    events.push(`📉 在售数量下降：${snap.onSale} → ${latest.onSale}`);
127	  }
128	  if (typeof latest.trafficWatch === 'number' && typeof snap.trafficWatch === 'number' && latest.trafficWatch > snap.trafficWatch) {
129	    events.push(`⚠️ 商品流量待关注增加：${snap.trafficWatch} → ${latest.trafficWatch}`);
130	    // 被动扫到的 watchItems 往往为空（限流商品散落在其它页）→ 主动点筛选把这几条捞出来，带链接点名。
131	    let items = Array.isArray(latest.watchItems) ? latest.watchItems : [];
132	    let total = latest.trafficWatch;
133	    const scan = await scanWatchViaTab();
134	    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
135	      items = scan.items;
136	      if (typeof scan.total === 'number') total = scan.total;
137	    }
138	    events.push(...itemLines(items, total));
139	  }
140	  // 「商品流量近期有下降」商品数增加（相对已建立的基准，首次不报）
141	  if (typeof latest.trafficDecline === 'number' && typeof snap.trafficDecline === 'number' && latest.trafficDecline > snap.trafficDecline) {
142	    events.push(`🔴 商品流量近期有下降增加：${snap.trafficDecline} → ${latest.trafficDecline}（本页可见）`);
143	    events.push(...itemLines(latest.declineItems, null));
144	  }
145	
146	  if (events.length > 0) {
147	    const lines = [`**🏬 ${name}**`, ...events, '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
148	    const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
149	    await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
150	  }
151	
152	  // 合并式更新该店基准快照（只覆盖本次拿到的数值），幂等只报一次。
153	  // 重新取一次 store：主动扫筛选期间 content 可能又上报过 latest，避免用旧闭包覆盖。
154	  const stores2 = await getStores();
155	  const s2 = stores2[name] || s;
156	  const L2 = s2.latest || latest;
157	  const newSnap = Object.assign({}, s2.snapshot || snap);
158	  if (typeof L2.onSale === 'number') newSnap.onSale = L2.onSale;
159	  if (typeof L2.total === 'number') newSnap.total = L2.total;
160	  if (typeof L2.trafficWatch === 'number') newSnap.trafficWatch = L2.trafficWatch;
161	  if (typeof L2.trafficDecline === 'number') newSnap.trafficDecline = L2.trafficDecline;
162	  newSnap.ts = Date.now();
163	  s2.snapshot = newSnap;
164	  stores2[name] = s2;
165	  await saveStores(stores2);
166	}
167	
168	// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
169	// items 为 content.js 扫「在售中」tab 得到的当前在售商品(productId+name+skc)。返回下架数量(供日志)。
170	async function diffOnSale(name, items, onSaleTabCount) {
171	  if (!Array.isArray(items) || !items.length) return 0; // 空 = 扫描失败或真 0，稳妥起见不动基准、不报
172	  const cfg = await getConfig();
173	  const stores = await getStores();
174	  const s = stores[name] || { latest: {}, snapshot: {} };
175	  // 防残缺扫描/筛选污染误判：以"扫描当时在干净视图下读到的「在售中 N」"为权威在售数
176	  // （content.js scanOnSaleList 复位后读的，不会被「商品流量待关注」筛选污染）；
177	  // 读不到才回退 countStatus 的 latest.onSale。扫到的商品数必须不少于它，否则视为没扫全 → 跳过。
178	  const known = (typeof onSaleTabCount === 'number' && onSaleTabCount > 0)
179	    ? onSaleTabCount
180	    : (s.latest && typeof s.latest.onSale === 'number' ? s.latest.onSale : null);
181	  if (known != null && items.length < known) return 0;
182	  const newMap = {};
183	  for (const it of items) if (it && it.productId) newMap[it.productId] = { name: it.name || '', skc: it.skc || '' };
184	  const prevMap = s.snapshot && s.snapshot.onSaleIds;
185	  let delistedCount = 0;
186	  if (prevMap && cfg.enabled) { // 首次无基准 → 只记录不报
187	    const delisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
188	    delistedCount = delisted.length;
189	    if (delisted.length) {
190	      const its = delisted.map((pid) => ({ productId: pid, name: prevMap[pid].name, skc: prevMap[pid].skc }));
191	      const lines = [`**🏬 ${name}**`, `📉 在售商品下架 ${delisted.length} 个（在售 ${Object.keys(prevMap).length} → ${items.length}）:`,
192	        ...itemLines(its, null), '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
193	      const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
194	      await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
195	    }
196	  }
197	  // 重新取一次 stores 再写：_diffAndAlert 可能在 diffOnSale 处理期间并发更新过 snapshot 的
198	  // 数值字段（onSale/trafficWatch 等），直接用初始读到的 s 会覆盖掉这些更新 → 基准腐败 → "数据后来不准"。
199	  const stores2 = await getStores();
200	  const s2 = stores2[name] || s;
201	  s2.snapshot = Object.assign({}, s2.snapshot || s.snapshot, { onSaleIds: newMap, onSaleIdsTs: Date.now() });
202	  stores2[name] = s2;
203	  await saveStores(stores2);
204	  return delistedCount;
205	}
206	
207	// 解析店铺名：优先用页面读到的店名；读不到则退回配置里手填的，再退回“当前店铺”
208	async function resolveStore(msgStore) {
209	  if (msgStore && String(msgStore).trim()) return String(msgStore).trim();
210	  const cfg = await getConfig();
211	  return (cfg.storeName && cfg.storeName.trim()) || '当前店铺';
212	}
213	
214	// ---------------- 消息处理 ----------------
215	chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
216	  (async () => {
217	    if (msg.type === 'capture') {
218	      const name = await resolveStore(msg.store);
219	      if (msg.kind === 'countStatus') {
220	        const p = parseCountStatus(msg.body);
221	        if (p && p.onSale != null) {
222	          await updateStoreLatest(name, { onSale: p.onSale, unpublished: p.unpublished, removed: p.removed, deleted: p.deleted });
223	          await diffAndAlert(name);
224	        }
225	      } else if (msg.kind === 'pageQuery') {
226	        const p = parsePageQuery(msg.body);
227	        if (p) await updateStoreLatest(name, { total: p.total });
228	      }
229	      sendResponse({ ok: true });
230	      return;
231	    }
232	    if (msg.type === 'chipStats') {
233	      const patch = {};
234	      if (typeof msg.trafficWatch === 'number') patch.trafficWatch = msg.trafficWatch;
235	      if (typeof msg.trafficDecline === 'number') patch.trafficDecline = msg.trafficDecline;
236	      if (Array.isArray(msg.watchItems)) patch.watchItems = msg.watchItems;
237	      if (Array.isArray(msg.declineItems)) patch.declineItems = msg.declineItems;
238	      if (Object.keys(patch).length) {
239	        const name = await resolveStore(msg.store);
240	        await updateStoreLatest(name, patch);
241	        await diffAndAlert(name);
242	      }
243	      sendResponse({ ok: true });
244	      return;
245	    }
246	    if (msg.type === 'getStatus') {
247	      sendResponse({ bgVersion: 'v6-下架漏报修复', config: await getConfig(), stores: await getStores(), ...(await chrome.storage.local.get(['lastAlert', 'lastCycle'])) });
248	      return;
249	    }
250	    if (msg.type === 'addStore') {
251	      const name = (msg.name || '').trim();
252	      if (!name) { sendResponse({ ok: false, msg: '店铺名不能为空' }); return; }
253	      const stores = await getStores();
254	      if (stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」已存在' }); return; }
255	      stores[name] = { latest: {}, snapshot: {} };
256	      await saveStores(stores);
257	      sendResponse({ ok: true, msg: '已添加「' + name + '」，下次轮巡将尝试切到该店抓数' });
258	      return;
259	    }
260	    if (msg.type === 'deleteStore') {
261	      const name = (msg.name || '').trim();
262	      const stores = await getStores();
263	      if (!stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」不存在' }); return; }
264	      delete stores[name];
265	      await saveStores(stores);
266	      sendResponse({ ok: true, msg: '已删除「' + name + '」' });
267	      return;
268	    }
269	    if (msg.type === 'checkNow') {
270	      sendResponse(await pollNow());
271	      return;
272	    }
273	    if (msg.type === 'cycleNow') {
274	      sendResponse(await cycleStores('manual'));
275	      return;
276	    }
277	    if (msg.type === 'testFeishu') {
278	      const cfg = await getConfig();
279	      const r = await sendFeishu(cfg.webhook, '✅ Temu 监测测试', ['这是一条测试消息，收到说明飞书配置正常。', '', `_${new Date().toLocaleString('zh-CN')}_`]);
280	      sendResponse(r);
281	      return;
282	    }
283	  })();
284	  return true;
285	});
286	
287	// ---------------- 自动轮巡（切遍每个店抓数，再切回原店；仅空闲时触发） ----------------
288	const IDLE_SECONDS = 240; // 无操作 4 分钟视为空闲
289	let cycling = false;
290	
291	async function getGoodsTab() {
292	  const tabs = await chrome.tabs.query({ url: 'https://agentseller.temu.com/*' });
293	  return tabs.find((t) => /goods\/list/.test(t.url || '')) || tabs[0] || null;
294	}
295	function sendTab(tabId, cmd) {
296	  return new Promise((resolve) => {
297	    try {
298	      chrome.tabs.sendMessage(tabId, cmd, (resp) => {
299	        if (chrome.runtime.lastError) resolve(null); else resolve(resp);
300	      });
301	    } catch (e) { resolve(null); }
302	  });
303	}
304	async function sendTabRetry(tabId, cmd, tries) {
305	  for (let i = 0; i < (tries || 8); i++) {
306	    const r = await sendTab(tabId, cmd);
307	    if (r) return r;
308	    await new Promise((res) => setTimeout(res, 1000)); // 页面重载后 content 未就绪，重试
309	  }
310	  return null;
311	}
312	function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
313	// 等某店在切换后被重新抓到（latest.ts 比切换前更新、且有 onSale）
314	async function waitForStoreCapture(name, sinceTs, timeout) {
315	  const t0 = Date.now();
316	  while (Date.now() - t0 < (timeout || 25000)) {
317	    const stores = await getStores();
318	    const L = stores[name] && stores[name].latest;
319	    if (L && typeof L.onSale === 'number' && (L.ts || 0) > sinceTs) return true;
320	    await sleep(1500);
321	  }
322	  return false;
323	}
324	
325	async function cycleStores(reason) {
326	  if (cycling) return { ok: false, msg: '轮巡进行中' };
327	  cycling = true;
328	  const log = [];
329	  try {
330	    const tab = await getGoodsTab();
331	    if (!tab) return { ok: false, msg: '没有打开的 Temu 商品页' };
332	    const cur = await sendTabRetry(tab.id, { cmd: 'ping' }, 5);
333	    const original = cur && cur.store;
334	    log.push('当前店：' + (original || '未知'));
335	
336	    // 店铺清单：优先用“已知店”（之前逛各店时按顶栏店名记下的，干净准确）；
337	    // 不足 2 个才去弹窗探测（探测会混入页面杂项英文，仅作兜底）。
338	    const known = Object.keys(await getStores()).filter((n) => n && n !== '当前店铺');
339	    let names;
340	    if (known.length >= 2) {
341	      names = known;
342	      log.push('店铺(已知)：' + names.join(', '));
343	    } else {
344	      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
345	      names = [...new Set([...((listed && listed.names) || []), ...known])].filter(Boolean);
346	      log.push('店铺(探测)：' + names.join(', '));
347	    }
348	    if (names.length === 0) return { ok: false, msg: '没识别到店铺清单' };
349	
350	    for (const name of names) {
351	      if (name === original) continue; // 原店最后再确认；先切别的
352	      const since = Date.now();
353	      const r = await sendTabRetry(tab.id, { cmd: 'switchTo', target: name }, 5);
354	      if (!r || !r.ok) { log.push('切到 ' + name + ' 失败：' + (r && r.msg)); continue; }
355	      const got = await waitForStoreCapture(name, since, 25000);
356	      log.push((got ? '✓ ' : '✗ ') + name);
357	      // 扫在售清单 → diff 出下架商品（带链接告警）
358	      if (got) {
359	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
360	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items, os.onSaleTabCount); if (d) log.push('  ↳下架' + d + '个'); }
361	      }
362	    }
363	    // 切回原店
364	    if (original) {
365	      const since = Date.now();
366	      await sendTabRetry(tab.id, { cmd: 'switchTo', target: original }, 5);
367	      const gotBack = await waitForStoreCapture(original, since, 25000);
368	      if (gotBack) {
369	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
370	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(original, os.items, os.onSaleTabCount); if (d) log.push('  ↳' + original + '下架' + d + '个'); }
371	      }
372	      log.push('已切回 ' + original);
373	    }
374	    const summary = log.join(' | ');
375	    await chrome.storage.local.set({ lastCycle: { ts: Date.now(), reason, summary } });
376	    return { ok: true, msg: summary };
377	  } finally { cycling = false; }
378	}
379	
380	async function pollNow() {
381	  const tab = await getGoodsTab();
382	  if (!tab) return { ok: false, msg: '未找到打开的 Temu 后台标签页，请先登录并打开商品列表页' };
383	  if (/goods\/list/.test(tab.url || '')) { await chrome.tabs.reload(tab.id, { bypassCache: false }); return { ok: true, msg: '已刷新后台商品页' }; }
384	  await chrome.tabs.update(tab.id, { url: GOODS_URL });
385	  return { ok: true, msg: '已导航到商品列表页' };
386	}
387	
388	// 定时：空闲则轮巡所有店，否则不打扰（靠随看随记覆盖当前店）
389	chrome.alarms.onAlarm.addListener((a) => {
390	  if (a.name !== 'poll') return;
391	  chrome.idle.queryState(IDLE_SECONDS, (state) => {
392	    if (state === 'idle' || state === 'locked') cycleStores('idle');
393	  });
394	});
395	
396	async function setupAlarm() {
397	  await chrome.storage.local.remove('trafficSample'); // 清早期诊断残留
398	  const cfg = await getConfig();
399	  await chrome.alarms.clear('poll');
400	  chrome.alarms.create('poll', { periodInMinutes: Math.max(1, cfg.intervalMinutes || 15) });
401	}
402	chrome.runtime.onInstalled.addListener(setupAlarm);
