1	// 运行在页面 MAIN world：hook window.fetch 与 XMLHttpRequest，
2	// 截获 Temu 后台商品接口的响应 JSON，通过 postMessage 传给 content.js（隔离世界）。
3	// 只读、不改请求；请求本身仍由页面自己发出（自带 cookie + anti-content 签名），故不触发风控。
4	(function () {
5	  if (window.__temuMonHooked) return;
6	  window.__temuMonHooked = true;
7	
8	  // 关注两个接口：countStatus（各状态计数，含在售中）、pageQuery（商品列表 + 流量字段）
9	  const MATCH = /visage-agent-seller\/product\/skc\/(countStatus|pageQuery)\b/;
10	  function kindOf(url) {
11	    if (/countStatus/.test(url)) return 'countStatus';
12	    if (/pageQuery/.test(url)) return 'pageQuery';
13	    return null;
14	  }
15	
16	  // 从请求头 / cookie 里找出当前店铺 id（多店铺时用来区分是哪个店）
17	  function findMallInHeaders(hdrs) {
18	    if (!hdrs) return null;
19	    for (const k of Object.keys(hdrs)) {
20	      if (/mall.?id/i.test(k) && /^\d{6,}$/.test(String(hdrs[k]).trim())) return String(hdrs[k]).trim();
21	    }
22	    return null;
23	  }
