1	import { log } from './logger.js';
2	import { closePopups } from './popups.js';
3	
4	/**
5	 * 抓取当前店铺（聚合「全球」视图）的监测指标：
6	 *   - onSaleCount          「在售中 N」数量（顶部状态 tab，beast-core-tab-itemLabel）
7	 *   - trafficWatchCount    「商品流量待关注」数量（点快速筛选 chip → 读「共有 N 条」）
8	 *   - trafficDeclineExists 是否存在「商品流量近期有下降」商品（用「批量处理流量下降商品」按钮存在性判断）
9	 *   - trafficAnomalyTotal  流量异常合计（当前 = 待关注数；下降无精确计数入口，单独用布尔信号告警）
10	 *
11	 * 说明：真实后台是 Temu 自研 beast-core UI 库，选择器优先用稳定的 data-testid。
12	 */
13	export async function scanStore(page, storeName, cfg) {
14	  // 先武装「拦截 countStatus 接口」的监听，再导航——导航会触发页面自身发出该请求，
15	  // 直接读其 JSON 拿在售等状态计数，比解析渲染出来的 tab 文本稳得多（不受渲染时机/弹窗遮挡影响）。
16	  const statusP = page
17	    .waitForResponse(
18	      (r) =>
19	        /visage-agent-seller\/product\/skc\/countStatus/.test(r.url()) &&
20	        r.request().method() === 'POST',
21	      { timeout: 20000 }
22	    )
23	    .catch(() => null);
24	  // 单次 commit 导航（重型 SPA 的既定策略，见 browser.js）；即便已在该页，重新导航也能拿到最新接口数据。
25	  await page.goto(cfg.goodsListUrl, { waitUntil: 'commit' }).catch(() => {});
26	  const statusResp = await statusP; // 等到 countStatus 返回（约等于首屏接口打完）
27	  await closePopups(page);
28	  await waitGrid(page); // 流量筛选仍需商品网格渲染出来
29	
30	  // 在售数量：优先读接口，失败回落解析 tab 文本
31	  let onSaleCount = readOnSaleFromStatus(await readStatusJson(statusResp));
32	  if (onSaleCount != null) {
33	    log.info(`在售数量读自 countStatus 接口：${onSaleCount}`);
34	  } else {
35	    onSaleCount = await readOnSaleCount(page);
36	    log.warn(`countStatus 接口未取到在售数量，回落解析 tab：${onSaleCount}`);
37	  }
38	
39	  const { trafficWatchCount, trafficDeclineExists } = await readTraffic(page);
40	  const trafficAnomalyTotal = trafficWatchCount ?? 0;
41	
42	  return {
43	    store: storeName,
44	    onSaleCount,
45	    trafficWatchCount,
46	    trafficDeclineExists,
47	    trafficAnomalyTotal,
48	  };
49	}
50	
51	/** 安全解析 countStatus 响应体为 JSON（失败返回 null） */
52	async function readStatusJson(resp) {
53	  if (!resp) return null;
54	  try {
55	    return await resp.json();
56	  } catch {
57	    return null;
58	  }
59	}
60	
61	/**
62	 * 从 countStatus 的 JSON 取「在售中」数量。
63	 * result.skcTopStatusCountList 里 skcTopStatus:100 → skcTotal = 在售中
64	 * （0=未发布 / 200=已下架 / 300=已删除）。
65	 */
66	function readOnSaleFromStatus(json) {
67	  const list = json?.result?.skcTopStatusCountList;
68	  if (!Array.isArray(list)) return null;
69	  const onSale = list.find((s) => s && s.skcTopStatus === 100);
70	  return onSale && typeof onSale.skcTotal === 'number' ? onSale.skcTotal : null;
71	}
72	
73	/** 等商品表格真正渲染出行 */
74	async function waitGrid(page) {
75	  await page
76	    .locator('[data-testid="beast-core-table-body-tr"]')
77	    .first()
78	    .waitFor({ state: 'visible', timeout: 20000 })
79	    .catch(() => {});
80	}
81	
82	/** 读「在售中 N」——tab 叶子文本形如「在售中 13」 */
83	async function readOnSaleCount(page) {
84	  const tabs = page.locator('[data-testid="beast-core-tab-itemLabel"]');
85	  const n = await tabs.count().catch(() => 0);
86	  for (let i = 0; i < n; i++) {
87	    const t = (await tabs.nth(i).innerText().catch(() => '')).trim();
88	    const m = t.match(/在售中\s*([\d,]+)/);
89	    if (m) return Number(m[1].replace(/,/g, ''));
90	  }
91	  // 兜底：纯文本匹配
92	  const loc = page.getByText(/在售中\s*[\d,]+/).first();
93	  const txt = await loc.innerText({ timeout: 2000 }).catch(() => '');
94	  const m = txt.match(/在售中\s*([\d,]+)/);
95	  return m ? Number(m[1].replace(/,/g, '')) : null;
96	}
97	
98	/** 读流量异常：点「商品流量待关注」筛选读计数 + 判「流量下降」是否存在 */
99	async function readTraffic(page) {
100	  let trafficWatchCount = null;
101	
102	  const chip = page.getByText('商品流量待关注', { exact: false }).first();
103	  if (await chip.isVisible({ timeout: 2000 }).catch(() => false)) {
104	    // 筛选偶发点了不生效（before==after）→ 最多重试 3 次，每次重置后重点，
105	    // 尽量拿到确切计数，减少「记为未知」的轮次（未知轮会拖累告警判断）。
106	    const MAX_TRY = 3;
107	    let after = null;
108	    let before = null;
109	    for (let attempt = 1; attempt <= MAX_TRY; attempt++) {
110	      before = await readTotal(page); // 筛选前的总数（如 408）
111	      await chip.click({ timeout: 3000 }).catch(() => {});
112	      // 关键：等列表真正刷新——「共有 N 条」的数值发生变化才算筛选生效（避免读到旧的总数）
113	      await page.waitForFunction((prev) => {
114	        const e = [...document.querySelectorAll('*')].find(
115	          (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
116	        );
117	        if (!e) return false;
118	        const m = e.textContent.match(/共有\s*([\d,]+)\s*条/);
119	        return m && Number(m[1].replace(/,/g, '')) !== prev;
120	      }, before, { timeout: 8000 }).catch(() => {});
121	      after = await readTotal(page);
122	      // 仅当筛选确实生效（数值变化且小于总数）才采纳，绝不把"未筛选的总数"当作待关注数
123	      if (after != null && before != null && after !== before && after < before) {
124	        trafficWatchCount = after;
125	        await clickReset(page);
126	        await page.waitForTimeout(2000);
127	        break;
128	      }
129	      // 本次未生效：重置后再试
130	      log.warn(`「商品流量待关注」筛选第 ${attempt}/${MAX_TRY} 次未生效(before=${before}, after=${after})。`);
131	      await clickReset(page);
132	      await page.waitForTimeout(2000);
133	    }
134	    if (trafficWatchCount == null) {
135	      log.warn('「商品流量待关注」多次重试仍未生效，本轮待关注计数记为未知。');
136	    }
137	  } else {
138	    log.warn('未找到「商品流量待关注」快速筛选 chip。');
139	  }
140	
141	  // 「商品流量近期有下降」没有独立筛选/计数入口，用批量处理按钮的存在性作为「有下降商品」信号
142	  const declineBtn = page.getByText('批量处理流量下降商品', { exact: false }).first();
143	  const trafficDeclineExists = await declineBtn.isVisible({ timeout: 1500 }).catch(() => false);
144	
145	  return { trafficWatchCount, trafficDeclineExists };
146	}
147	
148	/** 读列表底部「共有 N 条」 */
149	async function readTotal(page) {
150	  const txt = await page.evaluate(() => {
151	    const e = [...document.querySelectorAll('*')].find(
152	      (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
153	    );
154	    return e ? e.textContent.trim() : '';
155	  });
156	  const m = txt.match(/共有\s*([\d,]+)\s*条/);
157	  return m ? Number(m[1].replace(/,/g, '')) : null;
158	}
159	
160	/** 点「重置」清空快速筛选 */
161	async function clickReset(page) {
162	  const reset = page.getByText(/^重置$/).first();
163	  if (await reset.isVisible({ timeout: 1000 }).catch(() => false)) {
164	    await reset.click({ timeout: 2000 }).catch(() => {});
165	  }
166	}
