15	  log.info('等待登录完成…（最多 5 分钟）。登录并看到商品列表后即可，无需手动关闭窗口。');
16	
17	  const deadline = Date.now() + 5 * 60 * 1000;
18	  let ok = false;
19	  while (Date.now() < deadline) {
20	    // 窗口被手动关闭则提前结束
21	    if (page.isClosed()) { log.warn('检测到浏览器窗口已关闭，结束等待。'); break; }
22	    try {
23	      await page.waitForTimeout(3000);
