26	        .getByText(/商品列表|在售中|全部\s*\d+/)
27	        .first()
28	        .isVisible()
29	        .catch(() => false);
30	      if (loggedIn && !/login|signin/i.test(url)) { ok = true; break; }
31	    } catch (e) {
32	      // 登录页重定向/刷新期间的瞬时错误，忽略后继续轮询
33	      if (page.isClosed()) { log.warn('浏览器窗口已关闭，结束等待。'); break; }
34	      log.warn('轮询瞬时错误（忽略）：', e.message);
35	    }
36	  }
37	  if (ok) log.info('✅ 登录成功，session 已保存。之后可运行 npm run once / npm start。');
38	  else log.warn('⌛ 超时未检测到登录成功。若已登录可忽略；否则重试 npm run login。');
39	  await page.waitForTimeout(1500);
40	  await context.close().catch(() => {});
41	}
42	
43	async function startLoop() {
44	  log.info(`常驻监测启动，间隔 ${cfg.intervalMinutes} 分钟。Ctrl+C 退出。`);
45	  let loginFailStreak = 0; // 连续「未登录」轮次
46	  let loginAlertedAt = 0;  // 上次就登录过期发告警时的连续轮次（0 = 尚未告警）
47	  // 立即先跑一轮
48	  for (;;) {
49	    const t0 = Date.now();
50	    try {
51	      await runOnce(cfg);
52	      if (loginFailStreak > 0) {
53	        log.info('登录态已恢复，监测正常。');
54	        loginFailStreak = 0;
55	        loginAlertedAt = 0;
56	      }
57	    } catch (e) {
58	      log.error('本轮监测失败：', e.message);
59	      if (e.code === 'NOT_LOGGED_IN') {
60	        loginFailStreak++;
61	        await maybeAlertLoginExpiry(loginFailStreak, loginAlertedAt).then((sent) => {
62	          if (sent) loginAlertedAt = loginFailStreak;
63	        });
64	      } else {
65	        // 非登录类错误（导航/网关抖动等）不计入登录连续失败，避免误报登录过期
66	        loginFailStreak = 0;
67	      }
68	    }
69	    const elapsed = Date.now() - t0;
70	    const waitMs = Math.max(60_000, cfg.intervalMinutes * 60_000 - elapsed);
71	    log.info(`本轮结束，${Math.round(waitMs / 1000)} 秒后进入下一轮。`);
72	    await sleep(waitMs);
73	  }
74	}
75	
76	/**
77	 * 登录连续失败达到阈值时发飞书提醒；仍不恢复则每隔 loginRealertRounds 轮再提醒一次。
78	 * @returns {Promise<boolean>} 本轮是否发送了告警
79	 */
80	async function maybeAlertLoginExpiry(streak, alertedAt) {
81	  if (!cfg.alerts.loginExpiry) return false;
82	  const first = alertedAt === 0 && streak >= cfg.loginAlertAfterRounds;
83	  const repeat = alertedAt > 0 && (streak - alertedAt) >= cfg.loginRealertRounds;
84	  if (!first && !repeat) return false;
85	  const mins = streak * cfg.intervalMinutes;
86	  const ok = await sendFeishu(cfg, {
87	    title: '⚠️ Temu 监测中断：登录已过期',
88	    template: 'orange',
89	    lines: [
90	      `监测已连续 **${streak}** 轮（约 ${mins} 分钟）无法登录 Temu 后台，当前**没有在出数据**。`,
91	      '',
92	      '请到运行监测的电脑上重新登录一次：',
93	      '`cd temu-monitor` → `npm run login`（或运行「启动.bat」选 1）',
94	      '登录后监测会自动恢复，无需重启。',
95	      '',
96	      `_时间：${new Date().toLocaleString('zh-CN')}_`,
97	    ],
98	  }).catch(() => false);
99	  if (ok) log.info(`已发送登录过期飞书提醒（连续失败 ${streak} 轮）。`);
100	  return ok;
101	}
102	
